import * as React from "react";
import "./Modal.scss";
import ModalTitle from "./ModalTitle/ModalTitle";
import ModalContent from "./ModalContent/ModalContent";
import ModalActions from "./ModalActions/ModalActions";
import clsx from "clsx";
import { ButtonProps } from "../button";
import useWindowSize from "../../hooks/useWindowSize";

export interface ModalProps {
  /**
   * Unique identifier for modal instance
   */
  id: string;
  /**
   * Controls modal visibility
   */
  open: boolean;
  /**
   * Main heading text displayed in modal header
   */
  title: string;
  /**
   * Controls modal width size preset
   * @type {"xs" | "s" | "m" | "l" | "xl"}
   * @default "s"
   */
  size?: "xs" | "s" | "m" | "l" | "xl";
  /**
   * Label text for cancel button
   */
  cancelButtonLabel?: string;
  /**
   * Label text for primary action button
   */
  confirmButtonLabel?: string;
  /**
   * Label text for reset action button
   */
  resetButtonLabel?: string;
  /**
   * Callback for cancel button click (renders if provided)
   */
  onCancel?: () => void;
  /**
   * Callback for confirm button click (renders if provided)
   */
  onConfirm?: () => void;
  /**
   * Callback for reset button click (renders if provided)
   */
  onReset?: () => void;
  /**
   * Callback for modal close (via close button/ESC/outside click)
   */
  onClose?: () => void;
  /**
   * Toggle visibility of close button
   * @default true
   */
  showClose?: boolean;
  /**
   * Custom props for cancel button component
   * @type {Partial<ButtonProps>}
   */
  cancelButtonProps?: Partial<ButtonProps>;
  /**
   * Custom props for confirm button component
   * @type {Partial<ButtonProps>}
   */
  confirmButtonProps?: Partial<ButtonProps>;
  /**
   * Custom props for reset button component
   * @type {Partial<ButtonProps>}
   */
  resetButtonProps?: Partial<ButtonProps>;
  /**
   * Custom action buttons to override default button layout
   * @type {React.ReactNode}
   */
  customButtons?: React.ReactNode;
  /**
   * Optional thumbnail/image displayed in header
   * @type {React.ReactNode}
   */
  thumbnail?: React.ReactNode;
  /**
   * Enables non-modal dialog behavior (closes on outside click).
   *
   * @example
   * // Usage with click handler
   * const handleClick = (e) => {
   *     e.stopPropagation(); // important!
   *     setOpen(true);
   * };
   *
   * <Button onClick={handleClick}>Open Dialog</Button>
   *
   * @default false
   */
  nonModalDialogue?: boolean;
  /**
   * Allow modal container to exceed the default max-height of current size.
   */
  removeMaxHeight?: boolean;
  /**
   * Modal content (main body)
   */
  children?: React.ReactNode;
  /**
   * Additional CSS classes for modal-overlay. Pass a dummy className to remove positioning styles
   * when using a wrapper component to position modal.
   */
  className?: string;
}

const Modal = ({
  id,
  open,
  title,
  size = "s",
  cancelButtonLabel,
  confirmButtonLabel,
  resetButtonLabel,
  onCancel,
  onConfirm,
  onClose,
  onReset,
  showClose = true,
  cancelButtonProps,
  confirmButtonProps,
  resetButtonProps,
  customButtons,
  thumbnail,
  nonModalDialogue = false,
  removeMaxHeight = false,
  children,
  className,
}: ModalProps) => {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const { isMobile } = useWindowSize();

  React.useEffect(() => {
    const handleClickAway = (e: MouseEvent) => {
      e.stopPropagation();
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as HTMLElement)
      ) {
        onClose?.();
      }
    };
    const handleEsc = (e: KeyboardEvent) => {
      e.stopPropagation();
      if (e.key === "Escape") {
        onClose?.();
      }
    };
    if (open && nonModalDialogue) {
      document.addEventListener("click", handleClickAway);
      document.addEventListener("keydown", handleEsc);
    }
    return () => {
      document.removeEventListener("click", handleClickAway);
      document.removeEventListener("keydown", handleEsc);
    };
  }, [nonModalDialogue, open]);

  if (!open) return null;

  const contentTitle = thumbnail ? title : undefined;
  return (
    <div
      id={`${id}-overlay`}
      className={clsx("modal-overlay", !!className && className, {
        "modal-custom-overlay": !!className,
      })}
    >
      <div className={clsx("modal-base", { "modal-grid": !className })}>
        <div
          ref={containerRef}
          className={clsx(
            "modal-container",
            !isMobile && {
              "modal-extra-small": size === "xs",
              "modal-small": size === "s",
              "modal-medium": size === "m",
              "modal-large": size === "l",
              "modal-extra-large": size === "xl",
              "modal-long": removeMaxHeight,
            },
            isMobile && "modal-extra-large"
          )}
        >
          <ModalTitle
            id={id}
            title={title}
            thumbnail={thumbnail}
            onClose={onClose}
            showClose={showClose}
          />
          <ModalContent title={contentTitle}>{children}</ModalContent>
          <ModalActions
            id={id}
            cancelButtonLabel={cancelButtonLabel}
            confirmButtonLabel={confirmButtonLabel}
            resetButtonLabel = {resetButtonLabel}
            onCancel={onCancel}
            onConfirm={onConfirm}
            onReset = {onReset}
            cancelButtonProps={cancelButtonProps}
            confirmButtonProps={confirmButtonProps}
            resetButtonProps = {resetButtonProps}
            customButtons={customButtons}
          />
        </div>
      </div>
      {className && <div id="arrow" data-popper-arrow></div>}
    </div>
  );
};

export default Modal;
